import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { blockUser } from "../handlers/blockUser";
import type { ApiError } from "../runtime/client";
import type { UserPartition } from "../types/UserPartition";

type Data = Awaited<ReturnType<typeof blockUser>>;
type Vars = UserPartition;

export function useBlockUser(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => blockUser(vars),
    ...options,
  });
}
